// Signs release builds with the Play upload key. android/ is regenerated by prebuild, so the
// signing config is injected here instead of hand-edited.
//
// The key lives outside the repo; set these in ~/.gradle/gradle.properties:
//   ASCIICAM_UPLOAD_STORE_FILE=/absolute/path/to/asciicam-upload.keystore
//   ASCIICAM_UPLOAD_KEY_ALIAS=asciicam-upload
//   ASCIICAM_UPLOAD_STORE_PASSWORD=...
//   ASCIICAM_UPLOAD_KEY_PASSWORD=...
// Without them, release builds fall back to the debug key (fine locally, rejected by Play).
const { withAppBuildGradle } = require("expo/config-plugins");

const STORE_FILE = "ASCIICAM_UPLOAD_STORE_FILE";

const RELEASE_SIGNING_CONFIG = `
        release {
            if (project.hasProperty('${STORE_FILE}')) {
                storeFile file(${STORE_FILE})
                storePassword ASCIICAM_UPLOAD_STORE_PASSWORD
                keyAlias ASCIICAM_UPLOAD_KEY_ALIAS
                keyPassword ASCIICAM_UPLOAD_KEY_PASSWORD
            }
        }`;

const RELEASE_BUILD_SIGNING = `signingConfig project.hasProperty('${STORE_FILE}') ? signingConfigs.release : signingConfigs.debug`;

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (mod) => {
    let gradle = mod.modResults.contents;
    if (gradle.includes(STORE_FILE)) return mod;

    gradle = gradle.replace(/(signingConfigs\s*\{\s*debug\s*\{[^}]*\})/, `$1${RELEASE_SIGNING_CONFIG}`);
    gradle = gradle.replace(
      /(buildTypes\s*\{[\s\S]*?\brelease\s*\{[\s\S]*?)signingConfig signingConfigs\.debug/,
      `$1${RELEASE_BUILD_SIGNING}`,
    );

    if (!gradle.includes(RELEASE_SIGNING_CONFIG) || !gradle.includes(RELEASE_BUILD_SIGNING)) {
      throw new Error("with-release-signing: android/app/build.gradle no longer matches the expected template.");
    }

    mod.modResults.contents = gradle;
    return mod;
  });
};
